  "cavafala.help": "Grab mit GRABEN, halte SPRECHEN und sag, was du willst (z. B. „bridge“, „golden trampoline“, „double foam cannon“). Kein Mikro? Tipp auf die Tastatur.",
  "cavafala.help.1": "Grab, grab!",
  "cavafala.help.2": "Ich habe ein Fenster gefunden!",
  "cavafala.help.3": "Hier lang!",
  "cavafala.help.4": "So lockere Erde!",
  "cavafala.help2": "Grab mit GRABEN und SAG, was du bauen willst (z. B. „Brücke“, „goldenes Trampolin“, „doppelte Schaumkanone“). Kein Mikrofon? BAUEN öffnet die Rezepte.",
